  static const int NUM_ROWS = sizeof(rows) / sizeof(rows[0]);

  inline const Row* Find(long long id) {
    int low = 0;
    int high = NUM_ROWS - 1;
    while(low <= high) {
      const int mid = (low + high) / 2;
      if(rows[mid].id == id) {
        return &rows[mid];
      }
      if(rows[mid].id < id) {
        low = mid + 1;
      }
      else {
        high = mid - 1;
      }
    }
    return nullptr;
  }
